package databaseexamples

import (
    "context"
    "database/sql"
)

func FindCustomer(ctx context.Context, db *sql.DB, id int) (string, error) {
    var name string
    err := db.QueryRowContext(ctx,
        "SELECT name FROM customers WHERE id = $1", id).Scan(&name)
    return name, err
}

package databaseexamples

import (
    "context"
    "database/sql"
)

func Contacts(ctx context.Context, db *sql.DB) ([]string, error) {
    rows, err := db.QueryContext(ctx, "SELECT email FROM customers ORDER BY id")
    if err != nil { return nil, err }
    defer rows.Close()
    var contacts []string
    for rows.Next() {
        var email sql.NullString
        if err := rows.Scan(&email); err != nil { return nil, err }
        if email.Valid { contacts = append(contacts, email.String) }
    }
    return contacts, rows.Err()
}

package databaseexamples

import (
 "context"
 "database/sql"
 "fmt"
)

func AdjustPair(ctx context.Context, db *sql.DB, delta int) error {
 tx, err := db.BeginTx(ctx, nil)
 if err != nil { return err }
 defer tx.Rollback()
 for _, change := range []struct{ id, amount int }{{1, -delta}, {2, delta}} {
  result, err := tx.ExecContext(ctx, "UPDATE orders SET total = total + $1 WHERE id = $2", change.amount, change.id)
  if err != nil { return err }
  count, err := result.RowsAffected()
  if err != nil { return err }
  if count != 1 { return fmt.Errorf("missing order %d", change.id) }
 }
 return tx.Commit()
}

