import type { Client } from 'pg';

export async function findCustomer(client: Client, id: number): Promise<string | undefined> {
  const result = await client.query<{ name: string }>(
    'SELECT name FROM customers WHERE id = $1', [id],
  );
  return result.rows[0]?.name;
}

import type { Client } from 'pg';

export async function addCustomer(client: Client, id: number, name: string): Promise<void> {
  await client.query('BEGIN');
  try {
    await client.query(
      'INSERT INTO customers (id, name) VALUES ($1, $2)', [id, name],
    );
    await client.query('COMMIT');
  } catch (error) {
    await client.query('ROLLBACK');
    throw error;
  }
}

import type { Client } from 'pg';

export async function adjustPair(client: Client, delta: number): Promise<void> {
 await client.query('BEGIN');
 try {
  for (const [id, amount] of [[1, -delta], [2, delta]]) {
   const result = await client.query('UPDATE orders SET total = total + $1 WHERE id = $2', [amount, id]);
   if (result.rowCount !== 1) throw new Error('Missing transfer order');
  }
  await client.query('COMMIT');
 } catch (error) {
  await client.query('ROLLBACK');
  throw error;
 }
}

