import sqlite3

def find_customer(connection: sqlite3.Connection, customer_id: int) -> str | None:
    row = connection.execute(
        "SELECT name FROM customers WHERE id = ?", (customer_id,)
    ).fetchone()
    return None if row is None else row[0]

import sqlite3

def find_by_name(connection: sqlite3.Connection, name: str) -> list[tuple[int, str]]:
    return connection.execute(
        "SELECT id, name FROM customers WHERE name = :name ORDER BY id",
        {"name": name},
    ).fetchall()

import sqlite3

def add_customers(connection: sqlite3.Connection, rows: list[tuple[int, str]]) -> None:
    if connection.in_transaction:
        raise ValueError("Use an idle connection, not an existing transaction")
    with connection:
        connection.executemany("INSERT INTO customers (id, name) VALUES (?, ?)", rows)
